<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{useAppStore}from'../stores/app';import{ArrowRight}from'@lucide/vue';const store=useAppStore(),router=useRouter(),name=ref('');function go(){if(!name.value.trim())return;store.setName(name.value);store.finishOnboarding();router.push('/home')}</script>
<template><section class="name-page"><div class="mini-brand">Love Language ♡</div><div class="name-art"><img src="/assets/emma.png" alt="エマ"/></div><div class="speech">“What should I call you?”<small>あなたのこと、なんて呼べばいい？</small></div><div class="name-card"><p class="eyebrow">YOUR NAME</p><h1>あなたの名前を教えてください</h1><input v-model="name" maxlength="12" placeholder="例：Haru" @keyup.enter="go"/><p>あとからプロフィールで変更できます</p><button class="primary" :disabled="!name.trim()" @click="go">この名前で始める <ArrowRight :size="20"/></button></div></section></template>
